#ifndef THREAD_POOL_H
#define THREAD_POOL_H

#include <condition_variable>
#include <functional>
#include <list>
#include <mutex>
#include <optional>
#include <thread>
#include "log.h"
#include "util.h"

namespace ws {

class ThreadPool {
public:
    using Task = std::function<void()>;

    ThreadPool(std::optional<std::size_t> thread_count = std::nullopt, log::Logger::Ptr logger = log::RootLogger()) noexcept;
    ~ThreadPool() noexcept;

    ThreadPool(const ThreadPool&) = delete;
    ThreadPool(ThreadPool&&) = delete;
    ThreadPool& operator=(const ThreadPool&) = delete;
    ThreadPool& operator=(ThreadPool&&) = delete;

    void Start() noexcept;
    void Push(Task task) noexcept;
    void Close() noexcept;

private:
    log::Logger::Ptr logger_;
    std::mutex mtx_;
    std::atomic<bool> closed_;
    std::size_t thread_count_;
    std::condition_variable cond_;
    std::list<Task> tasks_;
    std::list<std::thread> threads_;

    void ExecProc() noexcept;
};

}

#endif // THREAD_POOL_H

#include "thread_pool.h"
#include <cassert>
#include <stdexcept>

namespace ws {

ThreadPool::ThreadPool(std::optional<std::size_t> thread_count, log::Logger::Ptr logger) noexcept
    : logger_(logger ? logger : log::RootLogger()),
      closed_(false),
      thread_count_(thread_count.value_or(std::thread::hardware_concurrency())) {}

ThreadPool::~ThreadPool() noexcept {
    Close();
    for (auto& thread : threads_) {
        if (thread.joinable()) {
            thread.join();
        }
    }
}

void ThreadPool::Start() noexcept {
    assert(closed_);
    closed_ = false;
    for (std::size_t i = 0; i < thread_count_; ++i) {
        threads_.emplace_back(&ThreadPool::ExecProc, this);
    }
}

void ThreadPool::Push(Task task) noexcept {
    assert(!closed_);
    std::lock_guard<std::mutex> lock(mtx_);
    tasks_.push_back(std::move(task));
    cond_.notify_one();
}

void ThreadPool::Close() noexcept {
    {
        std::lock_guard<std::mutex> lock(mtx_);
        closed_ = true;
    }
    cond_.notify_all();
}

void ThreadPool::ExecProc() noexcept {
    while (true) {
        Task task;
        {
            std::unique_lock<std::mutex> lock(mtx_);
            cond_.wait(lock, [this] { return closed_ || !tasks_.empty(); });
            if (closed_ && tasks_.empty()) {
                break;
            }
            task = std::move(tasks_.front());
            tasks_.pop_front();
        }
        try {
            task();
        } catch (const std::exception& e) {
            logger_->Log(log::LogLevel::Error, "Exception in task: " + std::string(e.what()));
        } catch (...) {
            logger_->Log(log::LogLevel::Error, "Unknown exception in task.");
        }
    }
}

}
